{
  "category_edits": [
    {
      "category": "architecture_interaction",
      "rationale": "Add a jointly trained 128-unit residual GELU block before the existing recency readout across all four category models. Zero initialization of the output projection preserves the initial recurrent mapping. Keep embeddings, scoring, loss, optimizer and history handling fixed; record the block width for matching predictor construction.",
      "edits": [
        {
          "find": "                 readout_half_life: float = 3.0):",
          "replace": "                 readout_half_life: float = 3.0, residual_ff_width: int = 128):"
        },
        {
          "find": "        self.output_emb = UnitNormItemEmbedding(\n            itemnum + 1, hidden_units, padding_idx=0,\n            _weight=self.item_emb.weight.detach().clone(),\n        )",
          "replace": "        self.output_emb = UnitNormItemEmbedding(\n            itemnum + 1, hidden_units, padding_idx=0,\n            _weight=self.item_emb.weight.detach().clone(),\n        )\n        self.residual_ff_width = residual_ff_width\n        self.residual_ff = nn.Sequential(\n            nn.Linear(hidden_units, residual_ff_width),\n            nn.GELU(),\n            nn.Linear(residual_ff_width, hidden_units),\n        )\n        nn.init.zeros_(self.residual_ff[0].bias)\n        nn.init.zeros_(self.residual_ff[2].weight)\n        nn.init.zeros_(self.residual_ff[2].bias)"
        },
        {
          "find": "        out, _ = self.gru(emb)\n        positions = torch.arange(seq.size(1), device=seq.device)",
          "replace": "        out, _ = self.gru(emb)\n        out = out + self.residual_ff(out)\n        positions = torch.arange(seq.size(1), device=seq.device)"
        },
        {
          "find": "            \"readout_half_life\": model.readout_half_life,\n",
          "replace": "            \"readout_half_life\": model.readout_half_life,\n            \"residual_ff_width\": model.residual_ff_width,\n"
        },
        {
          "find": "            readout_half_life=meta[\"readout_half_life\"],\n",
          "replace": "            readout_half_life=meta[\"readout_half_life\"],\n            residual_ff_width=meta[\"residual_ff_width\"],\n"
        }
      ]
    }
  ],
  "change_summary": "Add a zero-initialized residual feed-forward block before unchanged GRU recency pooling, with matching checkpoint metadata and generated predictor construction."
}
